<?php
declare(strict_types=1);

function passport_root(): string { return data_root().'/private-domain/passports'; }
function passport_file(): string { return passport_root().'/passports.json'; }
function service_file(): string { return passport_root().'/service-cases.json'; }
function passport_qr_dir(): string { return dirname(__DIR__).'/public/assets/passports'; }
function passport_ensure_dirs(): void { foreach([passport_root(),passport_qr_dir()] as $d)if(!is_dir($d))@mkdir($d,$d===passport_qr_dir()?0755:0750,true); }
function passports_all(): array { passport_ensure_dirs();try{return confidential_json_read(passport_file(),'atelierwood:passports:v1',[]);}catch(Throwable){return[];} }
function service_cases_all(): array { passport_ensure_dirs();try{return confidential_json_read(service_file(),'atelierwood:service-cases:v1',[]);}catch(Throwable){return[];} }
function passport_public_code(): string { return 'AWP-'.gmdate('ym').'-'.strtoupper(substr(bin2hex(random_bytes(5)),0,10)); }
function passport_by_code(string $code): ?array { foreach(passports_all() as $p)if(hash_equals((string)($p['public_code']??''),trim($code)))return$p;return null; }
function passport_by_guid(string $guid): ?array { foreach(passports_all() as $p)if(($p['guid']??'')===$guid)return$p;return null; }
function customer_passports(?string $customerGuid=null): array { $customerGuid=$customerGuid?:((string)(customer_identity()['guid']??''));$rows=array_values(array_filter(passports_all(),fn($p)=>($p['customer_guid']??'')===$customerGuid));usort($rows,fn($a,$b)=>strcmp((string)($b['issued_at']??''),(string)($a['issued_at']??'')));return$rows; }
function passport_generate_qr(array $passport): ?string { passport_ensure_dirs();$file=$passport['public_code'].'.png';$dest=passport_qr_dir().'/'.$file;$url=absolute_url('/passport/'.$passport['public_code']);$worker=dirname(__DIR__).'/python/qr_worker.py';$out=[];$code=1;exec('python3 '.escapeshellarg($worker).' '.escapeshellarg($url).' '.escapeshellarg($dest).' 2>&1',$out,$code);if($code!==0||!is_file($dest))return null;@chmod($dest,0644);return$file; }
function passport_issue_for_order(string $orderGuid): array {
    $order=order_by_guid($orderGuid);if(!$order)throw new RuntimeException('Order not found.');if(($order['status']??'')!=='DELIVERED')throw new RuntimeException('Passports can be issued only after delivery.');$existing=passports_all();$out=[];
    foreach((array)($order['items']??[]) as $idx=>$item){$source=$orderGuid.':'.$idx;foreach($existing as $p)if(($p['source_key']??'')===$source){$out[]=$p;continue 2;}$product=product_by_guid((string)($item['product_guid']??''));$years=1;$w=text_lower((string)($product['warranty']??''));if(preg_match('/(\d+)\s*year/',$w,$m))$years=max(1,(int)$m[1]);$issued=gmdate('c');$exp=gmdate('c',strtotime('+'.$years.' years'));
        $p=['guid'=>uuidv7(),'public_code'=>passport_public_code(),'source_key'=>$source,'order_guid'=>$orderGuid,'order_number'=>$order['number'],'customer_guid'=>$order['customer_guid'],'product_guid'=>$item['product_guid'],'sku'=>$item['sku'],'slug'=>$item['slug'],'name'=>$item['name'],'image'=>$item['image'],'material'=>$item['material'],'finish'=>$item['finish'],'configuration_snapshot'=>$item['configuration_snapshot']??[],'pricing_version'=>$item['pricing_version']??'','manufactured_at'=>$order['updated_at']??$issued,'issued_at'=>$issued,'warranty'=>['status'=>'ACTIVE','expires_at'=>$exp,'policy'=>$product['warranty']??'Standard Atelier Wood warranty'],'care'=>$product['care']??'Follow product care instructions.','design_fingerprint'=>hash('sha256',json_encode($item['configuration_snapshot']??[],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)),'qr_file'=>null];$p['qr_file']=passport_generate_qr($p);$existing[]=$p;$out[]=$p;
    }
    confidential_json_write(passport_file(),$existing,'atelierwood:passports:v1',foundation_checksum(passport_file()));audit_event('passport.issue',['order_guid'=>$orderGuid,'count'=>count($out)]);return$out;
}
function passport_public_projection(array $p): array { $product=product_by_guid((string)$p['product_guid']);return ['public_code'=>$p['public_code'],'name'=>$p['name'],'sku'=>$p['sku'],'material'=>$p['material'],'finish'=>$p['finish'],'manufactured_at'=>$p['manufactured_at'],'issued_at'=>$p['issued_at'],'warranty'=>$p['warranty'],'care'=>$p['care'],'image'=>$p['image'],'product_url'=>$product?url('/product/'.$product['slug']):null]; }
function passport_service_request(string $passportGuid,array $src): array { require_customer('/account/passports');$p=passport_by_guid($passportGuid);if(!$p||($p['customer_guid']??'')!==(customer_identity()['guid']??''))throw new RuntimeException('Passport not found.');$type=in_array(($src['type']??''),['CARE','WARRANTY','REPAIR','PARTS'],true)?$src['type']:'CARE';$message=trim((string)($src['message']??''));if(text_len($message)<10)throw new RuntimeException('Describe the service requirement.');$case=['guid'=>uuidv7(),'number'=>'AWS-'.strtoupper(substr(bin2hex(random_bytes(4)),0,8)),'passport_guid'=>$passportGuid,'customer_guid'=>$p['customer_guid'],'type'=>$type,'message'=>$message,'status'=>'OPEN','timeline'=>[['ts'=>gmdate('c'),'event'=>'OPEN','note'=>'Customer request received']],'created_at'=>gmdate('c'),'updated_at'=>gmdate('c')];$rows=service_cases_all();$rows[]=$case;confidential_json_write(service_file(),$rows,'atelierwood:service-cases:v1',foundation_checksum(service_file()));audit_event('passport.service_request',['case_guid'=>$case['guid'],'passport_guid'=>$passportGuid]);return$case; }
function customer_service_cases(?string $customerGuid=null): array { $customerGuid=$customerGuid?:((string)(customer_identity()['guid']??''));return array_values(array_filter(service_cases_all(),fn($c)=>($c['customer_guid']??'')===$customerGuid)); }
function passport_release_checks(): array { $passports=passports_all();$services=service_cases_all();$codes=array_column($passports,'public_code');$unique=count($codes)===count(array_unique($codes));$refs=true;$qr=true;foreach($passports as $p){if(!order_by_guid((string)($p['order_guid']??''))||!product_by_guid((string)($p['product_guid']??'')))$refs=false;if(!empty($p['qr_file'])&&!is_file(passport_qr_dir().'/'.$p['qr_file']))$qr=false;}return [
 ['name'=>'Product Passport encryption','ok'=>confidential_key()!==null&&confidential_crypto_available(),'detail'=>'Passport ownership, order links and service cases use encrypted private persistence.'],
 ['name'=>'Product Passport code uniqueness','ok'=>$unique,'detail'=>$unique?'Passport public codes are unique.':'Duplicate passport public code detected.'],
 ['name'=>'Product Passport reference integrity','ok'=>$refs,'detail'=>$refs?'Every passport resolves to a canonical order and product.':'Orphan passport detected.'],
 ['name'=>'Product Passport QR integrity','ok'=>$qr,'detail'=>$qr?'Generated QR files resolve.':'A passport QR file is missing.'],
 ['name'=>'Service case schema','ok'=>!array_filter($services,fn($c)=>empty($c['guid'])||empty($c['passport_guid'])||empty($c['status'])),'detail'=>'Service/warranty cases satisfy required identity and state fields.'],
]; }
